mapper.select:
SELECT 
FROM task


        AND status = #{status}


        AND priority = #{priority}


        AND project_id = #{projectId}


        AND assignee ILIKE '%' || #{assignee} || '%'


        AND assigner ILIKE '%' || #{assigner} || '%'


        AND (title ILIKE '%' || #{keyword} || '%'
        OR description ILIKE '%' || #{keyword} || '%')


ORDER BY created_at DESC
